"""Configuration validation and defaults (SPEC §2)."""

from typing import Any

REQUIRED_KEYS = ("host", "port", "user", "password", "dbname")

REPLICATION_METHODS = ("LOG_BASED", "INCREMENTAL", "FULL_TABLE")

DEFAULT_ITERSIZE = 20_000
DEFAULT_MAX_RUN_SECONDS = 43_200
DEFAULT_LOGICAL_POLL_TOTAL_SECONDS = 10_800


class ConfigurationError(Exception):
    """Invalid or incomplete tap configuration."""


def validate_config(config: dict[str, Any]) -> None:
    """Check required keys and cross-field constraints; raise ConfigurationError."""
    missing = [key for key in REQUIRED_KEYS if config.get(key) is None]
    if missing:
        msg = f"Missing required configuration keys: {', '.join(missing)}"
        raise ConfigurationError(msg)

    method = config.get("default_replication_method")
    if method is not None and method not in REPLICATION_METHODS:
        msg = (
            f"Invalid default_replication_method {method!r}; "
            f"expected one of {', '.join(REPLICATION_METHODS)}"
        )
        raise ConfigurationError(msg)

    if use_secondary(config):
        missing_secondary = [
            key for key in ("secondary_host", "secondary_port") if not config.get(key)
        ]
        if missing_secondary:
            raise ConfigurationError(
                "use_secondary requires additional configuration keys: "
                + ", ".join(missing_secondary)
            )


def _flag(config: dict[str, Any], key: str) -> bool:
    """Read a boolean setting, accepting real booleans and the legacy string "true".

    The reference implementation only honoured the exact string "true" for some
    flags (SPEC §10.2.2); we accept both real JSON booleans and that string.
    """
    value = config.get(key, False)
    if isinstance(value, str):
        return value.lower() == "true"
    return bool(value)


def use_ssl(config: dict[str, Any]) -> bool:
    return _flag(config, "ssl")


def debug_lsn(config: dict[str, Any]) -> bool:
    return _flag(config, "debug_lsn")


def use_secondary(config: dict[str, Any]) -> bool:
    return _flag(config, "use_secondary")


def break_at_end_lsn(config: dict[str, Any]) -> bool:
    value = config.get("break_at_end_lsn", True)
    return value.lower() == "true" if isinstance(value, str) else bool(value)


def itersize(config: dict[str, Any]) -> int:
    return int(config.get("itersize") or DEFAULT_ITERSIZE)


def max_run_seconds(config: dict[str, Any]) -> int:
    return int(config.get("max_run_seconds") or DEFAULT_MAX_RUN_SECONDS)


def logical_poll_total_seconds(config: dict[str, Any]) -> float:
    # A configured value of 0/absent falls back to the default (SPEC §2.2).
    return float(config.get("logical_poll_total_seconds") or DEFAULT_LOGICAL_POLL_TOTAL_SECONDS)


def filter_schemas(config: dict[str, Any]) -> list[str] | None:
    raw = config.get("filter_schemas")
    if not raw:
        return None
    return [schema.strip() for schema in raw.split(",") if schema.strip()]

"""Value conversion for FULL_TABLE / INCREMENTAL rows (SPEC §5)."""

import datetime
import json
import math
import sys
from decimal import Decimal
from typing import Any

if sys.version_info < (3, 11):
    from backports.datetime_fromisoformat import MonkeyPatch

    MonkeyPatch.patch_fromisoformat()


class UnsupportedValueError(Exception):
    """A value's Python class has no mapping to a Singer record value."""


def is_array_datatype(sql_datatype: str) -> bool:
    return sql_datatype.endswith("[]")


def array_element_datatype(sql_datatype: str) -> str:
    return sql_datatype[:-2]


def fix_hour_24(time_string: str) -> str:
    """Map PostgreSQL's legal 24:00:00 to 00:00:00 (SPEC §5, §10.2.4)."""
    if time_string.startswith("24"):
        return time_string.replace("24", "00", 1)
    return time_string


def convert_time(value: Any, with_timezone: bool) -> str:  # ruff:ignore[any-type]
    """Times become HH:MM:SS strings; tz-aware times convert to UTC first (SPEC §5)."""
    if isinstance(value, datetime.time):
        parsed = value
    else:
        parsed = datetime.time.fromisoformat(fix_hour_24(str(value)))
    if with_timezone and parsed.utcoffset() is not None:
        as_datetime = datetime.datetime.combine(datetime.date(2000, 1, 1), parsed)
        parsed = as_datetime.astimezone(datetime.timezone.utc).time()
    return parsed.strftime("%H:%M:%S")


def convert_timestamp(value: datetime.datetime) -> str:
    """Naive timestamps are assumed UTC (+00:00 appended); offsets are preserved."""
    if value.tzinfo is None:
        return value.isoformat() + "+00:00"
    return value.isoformat()


def convert_date(value: datetime.date) -> str:
    return value.isoformat() + "T00:00:00+00:00"


def selected_value_to_singer_value(value: Any, sql_datatype: str | None) -> Any:  # ruff:ignore[any-type]
    """Convert one column value from the driver's native typing (SPEC §5).

    Columns missing from the catalog metadata (``sql_datatype`` is None) fall
    through to the Python-class rules, mirroring how they pass through the
    extraction query unwrapped (SPEC §8.2).
    """
    if value is None:
        return None

    if sql_datatype and is_array_datatype(sql_datatype):
        if not isinstance(value, list):
            msg = f"Expected a list for array datatype {sql_datatype}, got {type(value).__name__}"
            raise UnsupportedValueError(msg)
        element_type = array_element_datatype(sql_datatype)
        return [
            # PostgreSQL does not enforce array dimensionality: nested lists
            # recurse as arrays, scalars use the element type's rule (SPEC §3.5, §5).
            selected_value_to_singer_value(
                element,
                sql_datatype if isinstance(element, list) else element_type,
            )
            for element in value
        ]

    if sql_datatype in ("json", "jsonb"):
        return json.loads(value) if isinstance(value, str) else value
    if sql_datatype == "bit":
        # bit(1) only; longer bit strings are unsupported and never synced.
        return value == "1" if isinstance(value, str) else bool(value)
    if sql_datatype == "time with time zone":
        return convert_time(value, with_timezone=True)
    if sql_datatype == "time without time zone":
        return convert_time(value, with_timezone=False)

    if isinstance(value, datetime.datetime):
        return convert_timestamp(value)
    if isinstance(value, datetime.date):
        return convert_date(value)
    if isinstance(value, datetime.timedelta):
        msg = "Cannot marshall a value of class datetime.timedelta"
        raise UnsupportedValueError(msg)
    if isinstance(value, Decimal):
        return None if value.is_nan() else value
    if isinstance(value, float):
        return None if (math.isnan(value) or math.isinf(value)) else value
    if isinstance(value, (bool, int, str)):
        return value
    if isinstance(value, dict):
        # hstore arrives as a dict when the driver mapping is registered.
        return value

    msg = f"Cannot marshall a value of class {type(value).__name__}"
    raise UnsupportedValueError(msg)

"""Catalog discovery (SPEC §3)."""

from __future__ import annotations

import sys
from dataclasses import dataclass
from decimal import Decimal
from typing import Any

import simplejson
import singer
from singer import metadata as metadata_module

from tap_postgres import config as cfg
from tap_postgres import db, stream_utils

LOGGER = singer.get_logger()

MAX_NUMERIC_PRECISION = 100
MAX_NUMERIC_SCALE = 38

INTEGER_TYPES = {"smallint", "integer", "bigint"}
FLOAT_TYPES = {"real", "double precision"}
JSON_TYPES = {"json", "jsonb"}
STRING_TYPES = {
    "character varying",
    "character",
    "text",
    "citext",
    "uuid",
    "money",
    "cidr",
    "inet",
    "macaddr",
}
TIMESTAMP_TYPES = {"date", "timestamp without time zone", "timestamp with time zone"}
TIME_TYPES = {"time without time zone", "time with time zone"}


class DiscoveryError(Exception):
    """Discovery could not produce a catalog."""


@dataclass
class ColumnInfo:
    column_name: str
    data_type: str  # base/element type name, domains resolved (e.g. "integer")
    is_array: bool
    is_enum: bool
    character_maximum_length: int | None
    numeric_precision: int | None
    numeric_scale: int | None
    is_primary_key: bool

    @property
    def sql_datatype(self) -> str:
        """The value published as `sql-datatype` metadata (SPEC §3.3)."""
        if self.is_array:
            return f"{self.data_type}[]"
        if (
            self.data_type == "bit"
            and self.character_maximum_length is not None
            and self.character_maximum_length > 1
        ):
            return f"bit({self.character_maximum_length})"
        return self.data_type


# One catalog row per visible column of every discoverable relation (SPEC §3.1).
COLUMN_SCAN_SQL = """
SELECT
  n.nspname                                                     AS schema_name,
  c.relname                                                     AS table_name,
  c.relkind                                                     AS relkind,
  c.reltuples::bigint                                           AS row_count,
  a.attname                                                     AS column_name,
  format_type(COALESCE(elem_base.oid, elem_t.oid, base_t.oid, t.oid), NULL) AS data_type,
  (elem_t.oid IS NOT NULL)                                      AS is_array,
  (COALESCE(elem_base.typtype, elem_t.typtype,
            base_t.typtype, t.typtype) = 'e')                   AS is_enum,
  information_schema._pg_char_max_length(
      COALESCE(elem_base.oid, elem_t.oid, base_t.oid, t.oid),
      CASE WHEN t.typtype = 'd' THEN t.typtypmod ELSE a.atttypmod END
  )                                                             AS character_maximum_length,
  information_schema._pg_numeric_precision(
      COALESCE(elem_base.oid, elem_t.oid, base_t.oid, t.oid),
      CASE WHEN t.typtype = 'd' THEN t.typtypmod ELSE a.atttypmod END
  )                                                             AS numeric_precision,
  information_schema._pg_numeric_scale(
      COALESCE(elem_base.oid, elem_t.oid, base_t.oid, t.oid),
      CASE WHEN t.typtype = 'd' THEN t.typtypmod ELSE a.atttypmod END
  )                                                             AS numeric_scale,
  (pk.indkey IS NOT NULL AND a.attnum = ANY (pk.indkey::int2[])) AS is_primary_key
FROM pg_catalog.pg_class c
JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
JOIN pg_catalog.pg_attribute a ON a.attrelid = c.oid
JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
LEFT JOIN pg_catalog.pg_type base_t
       ON t.typtype = 'd' AND base_t.oid = t.typbasetype
LEFT JOIN pg_catalog.pg_type elem_t
       ON COALESCE(base_t.typcategory, t.typcategory) = 'A'
      AND elem_t.oid = COALESCE(base_t.typelem, CASE WHEN t.typtype <> 'd' THEN t.typelem END)
LEFT JOIN pg_catalog.pg_type elem_base
       ON elem_t.typtype = 'd' AND elem_base.oid = elem_t.typbasetype
LEFT JOIN pg_catalog.pg_index pk
       ON pk.indrelid = c.oid AND pk.indisprimary
WHERE c.relkind IN ('r', 'v', 'm', 'p')
  AND n.nspname NOT IN ('pg_catalog', 'information_schema')
  AND n.nspname !~ '^pg_toast'
  AND a.attnum > 0
  AND NOT a.attisdropped
  AND has_column_privilege(c.oid, a.attnum, 'SELECT')
"""


def base_recursive_definitions() -> dict[str, Any]:
    """The self-referential array item schemas present in every stream (SPEC §3.5)."""
    definitions: dict[str, Any] = {}
    for name, json_type in (
        ("integer", "integer"),
        ("number", "number"),
        ("string", "string"),
        ("boolean", "boolean"),
        ("object", "object"),
    ):
        definition_name = f"sdc_recursive_{name}_array"
        definitions[definition_name] = {
            "type": ["null", json_type, "array"],
            "items": {"$ref": f"#/definitions/{definition_name}"},
        }
    definitions["sdc_recursive_timestamp_array"] = {
        "type": ["null", "string", "array"],
        "format": "date-time",
        "items": {"$ref": "#/definitions/sdc_recursive_timestamp_array"},
    }
    return definitions


def capped_precision_and_scale(
    numeric_precision: int | None, numeric_scale: int | None
) -> tuple[int, int]:
    """Default unconstrained numerics to 100/38 and clamp declared values (SPEC §3.4)."""
    precision = MAX_NUMERIC_PRECISION if numeric_precision is None else numeric_precision
    scale = MAX_NUMERIC_SCALE if numeric_scale is None else numeric_scale
    if precision > MAX_NUMERIC_PRECISION:
        LOGGER.warning(
            "Capping decimal precision %s to %s; values may be truncated",
            precision,
            MAX_NUMERIC_PRECISION,
        )
        precision = MAX_NUMERIC_PRECISION
    if scale > MAX_NUMERIC_SCALE:
        LOGGER.warning(
            "Capping decimal scale %s to %s; values may be truncated", scale, MAX_NUMERIC_SCALE
        )
        scale = MAX_NUMERIC_SCALE
    return precision, scale


def numeric_constraints(precision: int, scale: int) -> dict[str, Decimal]:
    return {
        "exclusiveMinimum": -(Decimal(10) ** (precision - scale)),
        "exclusiveMaximum": Decimal(10) ** (precision - scale),
        "multipleOf": Decimal(10) ** -scale,
    }


def _with_nullability(types: list[str], is_primary_key: bool) -> list[str]:
    """PK columns omit "null"; everything else is nullable, "null" first (SPEC §3.4)."""
    if is_primary_key:
        return types
    return ["null", *types]


def _scalar_column_schema(column: ColumnInfo) -> dict[str, Any]:
    data_type = column.data_type
    pk = column.is_primary_key

    if data_type in INTEGER_TYPES:
        bits = {"smallint": 16, "integer": 32, "bigint": 64}[data_type]
        return {
            "type": _with_nullability(["integer"], pk),
            "minimum": -(2 ** (bits - 1)),
            "maximum": 2 ** (bits - 1) - 1,
        }
    if data_type in ("numeric", "decimal"):
        precision, scale = capped_precision_and_scale(
            column.numeric_precision, column.numeric_scale
        )
        return {
            "type": _with_nullability(["number"], pk),
            **numeric_constraints(precision, scale),
        }
    if data_type in FLOAT_TYPES:
        return {"type": _with_nullability(["number"], pk)}
    if data_type == "boolean":
        return {"type": _with_nullability(["boolean"], pk)}
    if data_type == "bit":
        if column.character_maximum_length is not None and column.character_maximum_length > 1:
            return {}  # unsupported (SPEC §3.4)
        return {"type": _with_nullability(["boolean"], pk)}
    if data_type in ("character varying", "character"):
        schema: dict[str, Any] = {"type": _with_nullability(["string"], pk)}
        if column.character_maximum_length is not None:
            schema["maxLength"] = column.character_maximum_length
        return schema
    if data_type in STRING_TYPES or column.is_enum:
        return {"type": _with_nullability(["string"], pk)}
    if data_type in JSON_TYPES:
        return {"type": _with_nullability(["object", "array"], pk)}
    if data_type == "hstore":
        return {"type": _with_nullability(["object"], pk), "properties": {}}
    if data_type in TIMESTAMP_TYPES:
        return {"type": _with_nullability(["string"], pk), "format": "date-time"}
    if data_type in TIME_TYPES:
        return {"type": _with_nullability(["string"], pk), "format": "time"}
    return {}  # unmapped: unsupported


def _array_column_schema(column: ColumnInfo, definitions: dict[str, Any]) -> dict[str, Any]:
    """Route the element type to a recursive definition (SPEC §3.5)."""
    element_type = column.data_type
    if element_type in ("numeric", "decimal"):
        precision, scale = capped_precision_and_scale(
            column.numeric_precision, column.numeric_scale
        )
        definition_name = f"sdc_recursive_decimal_{precision}_{scale}_array"
        definitions[definition_name] = {
            "type": ["null", "number", "array"],
            **numeric_constraints(precision, scale),
            "items": {"$ref": f"#/definitions/{definition_name}"},
        }
    elif element_type in INTEGER_TYPES:
        definition_name = "sdc_recursive_integer_array"
    elif element_type in FLOAT_TYPES:
        definition_name = "sdc_recursive_number_array"
    elif element_type in ("boolean", "bit"):
        definition_name = "sdc_recursive_boolean_array"
    elif element_type in JSON_TYPES or element_type == "hstore":
        definition_name = "sdc_recursive_object_array"
    elif element_type in TIMESTAMP_TYPES:
        definition_name = "sdc_recursive_timestamp_array"
    else:
        definition_name = "sdc_recursive_string_array"

    return {
        "type": _with_nullability(["array"], column.is_primary_key),
        "items": {"$ref": f"#/definitions/{definition_name}"},
    }


def column_schema(column: ColumnInfo, definitions: dict[str, Any]) -> dict[str, Any]:
    if column.is_array:
        return _array_column_schema(column, definitions)
    return _scalar_column_schema(column)


def build_stream_entry(
    schema_name: str,
    table_name: str,
    is_view: bool,
    row_count: int,
    database_name: str,
    columns: list[ColumnInfo],
) -> dict[str, Any]:
    definitions = base_recursive_definitions()
    properties: dict[str, Any] = {}
    mdata: dict[Any, Any] = {}

    primary_keys: list[str] = []
    for column in columns:
        schema = column_schema(column, definitions)
        properties[column.column_name] = schema
        unsupported = schema == {}
        if column.is_primary_key:
            primary_keys.append(column.column_name)
        if unsupported:
            inclusion = "unsupported"
        elif column.is_primary_key:
            inclusion = "automatic"
        else:
            inclusion = "available"
        mdata["properties", column.column_name] = {
            "sql-datatype": column.sql_datatype,
            "inclusion": inclusion,
            "selected-by-default": not unsupported,
        }

    mdata[()] = {
        "table-key-properties": [] if is_view else primary_keys,
        "schema-name": schema_name,
        "database-name": database_name,
        "row-count": row_count,
        "is-view": is_view,
    }

    return {
        "table_name": table_name,
        "stream": table_name,
        "tap_stream_id": f"{schema_name}-{table_name}",
        "schema": {
            "type": "object",
            "properties": properties,
            "definitions": definitions,
        },
        "metadata": metadata_module.to_list(mdata),
    }


def discover_streams(
    connection: db.ConnectionProtocol,
    *,
    itersize: int,
    filter_schemas: list[str] | None = None,
    tables: list[tuple[str, str]] | None = None,
) -> list[dict[str, Any]]:
    """Inspect the database and return catalog stream entries (SPEC §3).

    ``tables`` limits the scan to specific ``(schema_name, table_name)`` pairs,
    which is how sync refreshes the schemas of selected streams (SPEC §4.1).
    """
    database_name = db.fetch_scalar(connection, "SELECT current_database()")

    sql = COLUMN_SCAN_SQL
    params: list[Any] = []
    if filter_schemas:
        sql += "  AND n.nspname = ANY (%s)\n"
        params.append(filter_schemas)
    if tables:
        sql += "  AND (n.nspname, c.relname) IN %s\n"
        params.append(tuple(tables))
    sql += "ORDER BY n.nspname, c.relname, a.attname"

    streams: list[dict[str, Any]] = []
    current_key: tuple[str, str] | None = None
    current_columns: list[ColumnInfo] = []
    current_relkind = ""
    current_row_count = 0

    def flush() -> None:
        if current_key is None:
            return
        schema_name, table_name = current_key
        streams.append(
            build_stream_entry(
                schema_name=schema_name,
                table_name=table_name,
                is_view=current_relkind in ("v", "m"),
                row_count=current_row_count,
                database_name=database_name,
                columns=current_columns,
            )
        )

    cursor = db.named_cursor(connection, itersize)
    try:
        cursor.execute(sql, params or None)
        for (
            schema_name,
            table_name,
            relkind,
            row_count,
            column_name,
            data_type,
            is_array,
            is_enum,
            character_maximum_length,
            numeric_precision,
            numeric_scale,
            is_primary_key,
        ) in cursor:
            key = (schema_name, table_name)
            if key != current_key:
                flush()
                current_key = key
                current_columns = []
                current_relkind = relkind
                current_row_count = row_count
            current_columns.append(
                ColumnInfo(
                    column_name=column_name,
                    data_type=data_type,
                    is_array=is_array,
                    is_enum=is_enum,
                    character_maximum_length=character_maximum_length,
                    numeric_precision=numeric_precision,
                    numeric_scale=numeric_scale,
                    is_primary_key=is_primary_key,
                )
            )
        flush()
    finally:
        cursor.close()

    return streams


def do_discovery(
    connection: db.ConnectionProtocol,
    *,
    itersize: int,
    filter_schemas: list[str] | None,
) -> None:
    """Discovery mode: write the catalog to stdout (SPEC §3.1)."""
    streams = discover_streams(connection, itersize=itersize, filter_schemas=filter_schemas)
    if not streams:
        msg = "No tables discovered. Check database permissions and the filter_schemas setting."
        raise DiscoveryError(msg)
    dump_catalog(streams)


# Metadata keys produced by discovery; anything else is consumer-added
# (selected, replication-method, replication-key, view-key-properties, ...)
# and must survive a schema refresh (SPEC §4.1 step 3).
STREAM_DISCOVERABLE_METADATA = {
    "table-key-properties",
    "schema-name",
    "database-name",
    "row-count",
    "is-view",
}
COLUMN_DISCOVERABLE_METADATA = {"sql-datatype", "inclusion", "selected-by-default"}


def merge_refreshed_metadata(
    old_metadata: list[dict[str, Any]], fresh_metadata: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Fresh discoverable metadata, overlaid with the old non-discoverable metadata."""
    old_map = metadata_module.to_map(old_metadata)
    new_map = metadata_module.to_map(fresh_metadata)
    for breadcrumb, entry in old_map.items():
        discoverable = (
            STREAM_DISCOVERABLE_METADATA if breadcrumb == () else COLUMN_DISCOVERABLE_METADATA
        )
        for key, value in entry.items():
            if key in discoverable:
                continue
            if breadcrumb == () or breadcrumb in new_map:
                new_map.setdefault(breadcrumb, {})[key] = value
    return metadata_module.to_list(new_map)


def refresh_streams_schema(
    config: dict[str, Any], streams: list[dict[str, Any]], dbname: str | None = None
) -> None:
    """Replace each stream's schema and discoverable metadata in place (SPEC §4.1 step 3).

    Guarantees the sync works against the live table structure rather than a
    stale catalog, while preserving selection/replication metadata.
    """
    tables = []
    for stream in streams:
        tables.append((stream_utils.schema_name(stream), stream["table_name"]))

    connection = db.open_connection(config, dbname=dbname)
    try:
        fresh_streams = discover_streams(connection, itersize=cfg.itersize(config), tables=tables)
    finally:
        connection.close()
    fresh_by_id = {fresh["tap_stream_id"]: fresh for fresh in fresh_streams}

    for stream in streams:
        fresh = fresh_by_id.get(stream["tap_stream_id"])
        if fresh is None:
            msg = f"Selected stream {stream['tap_stream_id']} no longer exists in the database"
            raise DiscoveryError(msg)
        stream["schema"] = fresh["schema"]
        stream["metadata"] = merge_refreshed_metadata(stream.get("metadata", []), fresh["metadata"])


def dump_catalog(streams: list[dict[str, Any]]) -> None:
    # simplejson keeps Decimal schema constraints (e.g. multipleOf) precise.
    simplejson.dump({"streams": streams}, sys.stdout, indent=2, use_decimal=True)
    sys.stdout.write("\n")
    sys.stdout.flush()

"""Helpers shared by the sync strategies: metadata access and message emission (SPEC §4.4)."""

import copy
from typing import Any

import singer
from singer import metadata as metadata_module

LOGGER = singer.get_logger()


class InvalidCatalogError(Exception):
    """The input catalog is missing fields the tap needs to sync a stream."""


def metadata_map(stream: dict[str, Any]) -> dict[Any, Any]:
    return metadata_module.to_map(stream.get("metadata", []))


def stream_metadata(stream: dict[str, Any]) -> dict[str, Any]:
    return metadata_map(stream).get((), {})


def write_stream_metadata(stream: dict[str, Any], key: str, value: Any) -> None:  # ruff:ignore[any-type]
    """Set one stream-level (empty breadcrumb) metadata entry in place."""
    for entry in stream.setdefault("metadata", []):
        if not entry.get("breadcrumb"):
            entry.setdefault("metadata", {})[key] = value
            return
    stream["metadata"].append({"breadcrumb": [], "metadata": {key: value}})


def schema_name(stream: dict[str, Any]) -> str:
    """The stream's `schema-name` metadata; validated at sync start (SPEC §4.4)."""
    name = stream_metadata(stream).get("schema-name")
    if not name:
        stream_id = stream.get("tap_stream_id", "<unknown>")
        msg = f"Stream {stream_id} has no schema-name metadata"
        raise InvalidCatalogError(msg)
    return name


def validate_and_normalize_stream(stream: dict[str, Any]) -> None:
    """Check a selected catalog entry and fill in derivable fields, in place.

    Consumers occasionally hand-write catalogs, so anything derivable is
    repaired (`table_name` from `stream`, `schema-name` from `tap_stream_id`);
    anything else missing is a descriptive fatal error (SPEC §9).
    """
    missing = [field for field in ("tap_stream_id", "stream") if not stream.get(field)]
    if missing:
        msg = f"Catalog stream entry is missing required fields: {', '.join(missing)}"
        raise InvalidCatalogError(msg)
    stream_id = stream["tap_stream_id"]

    if not stream.get("table_name"):
        stream["table_name"] = stream["stream"]

    json_schema = stream.get("schema")
    if not isinstance(json_schema, dict) or not isinstance(json_schema.get("properties"), dict):
        msg = f"Stream {stream_id} has no JSON schema with a properties map"
        raise InvalidCatalogError(msg)

    if not stream_metadata(stream).get("schema-name"):
        # tap_stream_id is `<schema_name>-<table_name>` (SPEC §3.2), so the
        # schema name is recoverable when the id follows that shape.
        suffix = f"-{stream['table_name']}"
        if stream_id.endswith(suffix) and len(stream_id) > len(suffix):
            derived = stream_id[: -len(suffix)]
            LOGGER.info(
                "Stream %s has no schema-name metadata; derived %r from tap_stream_id",
                stream_id,
                derived,
            )
            write_stream_metadata(stream, "schema-name", derived)
        else:
            msg = (
                f"Stream {stream_id} has no schema-name metadata and it cannot be "
                "derived from tap_stream_id; re-run discovery or add it to the catalog"
            )
            raise InvalidCatalogError(msg)


def is_view(stream: dict[str, Any]) -> bool:
    return bool(stream_metadata(stream).get("is-view"))


def dest_stream_name(stream: dict[str, Any]) -> str:
    """Destination stream name: `<schema-name>-<stream>` (SPEC §4.4)."""
    return f"{schema_name(stream)}-{stream['stream']}"


def key_properties(stream: dict[str, Any]) -> list[str]:
    """`table-key-properties`, or `view-key-properties` for views (SPEC §4.4)."""
    md = stream_metadata(stream)
    if md.get("is-view"):
        return md.get("view-key-properties") or []
    return md.get("table-key-properties") or []


def _truthy_metadata(value: Any, default: bool) -> bool:  # ruff:ignore[any-type]
    if value is None:
        return default
    if isinstance(value, str):
        return value.lower() == "true"
    return bool(value)


def is_stream_selected(stream: dict[str, Any]) -> bool:
    return _truthy_metadata(stream_metadata(stream).get("selected"), default=False)


def selected_columns(stream: dict[str, Any]) -> list[str]:
    """Columns to sync, in alphabetical order (SPEC §4.1 step 5).

    `automatic` columns are always synced; `available` columns default to
    selected when no `selected` metadata is present; `unsupported` never sync.
    """
    md_map = metadata_map(stream)
    columns = []
    for column in stream["schema"].get("properties", {}):
        column_md = md_map.get(("properties", column), {})
        inclusion = column_md.get("inclusion")
        if inclusion == "automatic" or (
            inclusion == "available" and _truthy_metadata(column_md.get("selected"), default=True)
        ):
            columns.append(column)
    return sorted(columns)


def sql_datatype_for_column(stream: dict[str, Any], column: str) -> str | None:
    return metadata_map(stream).get(("properties", column), {}).get("sql-datatype")


def replication_key(stream: dict[str, Any]) -> str | None:
    return stream_metadata(stream).get("replication-key")


def write_schema_message(stream: dict[str, Any], bookmark_properties: list[str]) -> None:
    singer.write_message(
        singer.SchemaMessage(
            stream=dest_stream_name(stream),
            schema=stream["schema"],
            key_properties=key_properties(stream),
            bookmark_properties=bookmark_properties,
        )
    )


def write_state_message(state: dict[str, Any]) -> None:
    """STATE messages carry a deep copy of the complete state (SPEC §4.4)."""
    singer.write_message(singer.StateMessage(value=copy.deepcopy(state)))

"""Sync orchestration (SPEC §4)."""

from pathlib import Path
from typing import Any

import singer
from singer import bookmarks

from tap_postgres import config as cfg
from tap_postgres import db, discovery, full_table, incremental, logical, stream_utils
from tap_postgres.batch import ArrowBatchSource, BatchConfig

LOGGER = singer.get_logger()


class SyncError(Exception):
    """Unsupported replication situation."""


def resolve_replication_method(stream: dict[str, Any], config: dict[str, Any]) -> str:
    method = stream_utils.stream_metadata(stream).get("replication-method") or config.get(
        "default_replication_method"
    )
    if method not in cfg.REPLICATION_METHODS:
        msg = (
            f"Unrecognized replication method {method!r} for stream "
            f"{stream['tap_stream_id']}; expected one of {', '.join(cfg.REPLICATION_METHODS)}"
        )
        raise SyncError(msg)
    return method


def reset_state_on_method_change(
    state: dict[str, Any], stream_id: str, method: str, replication_key: str | None
) -> dict[str, Any]:
    """Wipe bookmarks when the replication method or incremental key changed (SPEC §4.2)."""
    previous_method = singer.get_bookmark(state, stream_id, "last_replication_method")
    if previous_method is not None and previous_method != method:
        LOGGER.info(
            "Replication method of stream %s changed from %s to %s: wiping bookmarks",
            stream_id,
            previous_method,
            method,
        )
        state["bookmarks"][stream_id] = {}
    if method == "INCREMENTAL":
        previous_key = singer.get_bookmark(state, stream_id, "replication_key")
        if previous_key is not None and previous_key != replication_key:
            LOGGER.info(
                "Replication key of stream %s changed from %s to %s: wiping bookmarks",
                stream_id,
                previous_key,
                replication_key,
            )
            state["bookmarks"][stream_id] = {}
    return singer.write_bookmark(state, stream_id, "last_replication_method", method)


def classify_log_based_work(state: dict[str, Any], stream_id: str) -> str:
    """Decide between the initial snapshot phase and pure logical streaming (SPEC §4.3)."""
    has_xmin = singer.get_bookmark(state, stream_id, "xmin") is not None
    has_lsn = singer.get_bookmark(state, stream_id, "lsn") is not None
    if not has_xmin and not has_lsn:
        return "snapshot"
    if has_xmin and has_lsn:
        return "snapshot"  # resume an interrupted initial copy
    if has_lsn:
        return "logical"
    msg = f"Stream {stream_id} has an xmin bookmark but no lsn bookmark: inconsistent state"
    raise SyncError(msg)


def _database_name(stream: dict[str, Any]) -> str | None:
    """The stream's `database-name` metadata; callers fall back to the config dbname."""
    return stream_utils.stream_metadata(stream).get("database-name")


def sync_traditional_stream(
    config: dict[str, Any],
    stream: dict[str, Any],
    state: dict[str, Any],
    method: str,
    end_lsn: int | None,
    batch_config: BatchConfig | None = None,
) -> dict[str, Any]:
    stream_id = stream["tap_stream_id"]
    LOGGER.info("Syncing stream %s with method %s", stream_id, method)

    columns = stream_utils.selected_columns(stream)
    if not columns:
        LOGGER.warning("No columns selected for stream %s: skipping it", stream_id)
        return state

    if method == "LOG_BASED" and stream_utils.is_view(stream):
        msg = f"LOG_BASED replication is not supported for view {stream_id}"
        raise SyncError(msg)

    state = singer.set_currently_syncing(state, stream_id)

    # The source is either an ADBC batch source or a psycopg2 connection,
    # never both: BATCH mode opens no psycopg2 connection at all, and
    # LOG_BASED (including its initial snapshot) always uses RECORD messages.
    dbname = _database_name(stream)
    source: db.ConnectionProtocol | ArrowBatchSource
    if batch_config is not None and method in ("FULL_TABLE", "INCREMENTAL"):
        source = ArrowBatchSource(batch_config, dbname=dbname)
    else:
        source = db.open_connection(config, dbname=dbname)
        db.register_type_adapters(source)
    try:
        if method == "FULL_TABLE":
            state, version, first_run = full_table.prepare(state, stream)
            state = full_table.sync_table(
                source, stream, state, config, columns, version, first_run
            )
        elif method == "INCREMENTAL":
            state = incremental.sync_table(source, stream, state, config, columns)
        elif method == "LOG_BASED":
            # Initial snapshot phase: bookmark the end LSN captured at run
            # start so the snapshot and the WAL stream dovetail (SPEC §6.3.4).
            if singer.get_bookmark(state, stream_id, "lsn") is None:
                state = singer.write_bookmark(state, stream_id, "lsn", end_lsn)
            state, version, first_run = full_table.prepare(state, stream)
            state = full_table.sync_table(
                source, stream, state, config, columns, version, first_run
            )
    finally:
        if not isinstance(source, ArrowBatchSource):
            source.close()

    state = singer.set_currently_syncing(state, None)
    stream_utils.write_state_message(state)
    return state


def do_sync(
    config: dict[str, Any],
    catalog: dict[str, Any],
    state: dict[str, Any],
    state_file: Path | None,
) -> dict[str, Any]:
    state.setdefault("bookmarks", {})

    # Fail fast on a bad batch_config (or a missing 'arrow' extra) before any
    # sync work starts. LOG_BASED streams always stay in RECORD mode (MEL-541).
    batch_config = BatchConfig.from_config(config)

    selected = [
        stream for stream in catalog.get("streams", []) if stream_utils.is_stream_selected(stream)
    ]
    if not selected:
        LOGGER.info("No streams marked as selected in the catalog: nothing to sync")
        return state

    # Fail fast on malformed catalog entries; fill in derivable fields (SPEC §9).
    for stream in selected:
        stream_utils.validate_and_normalize_stream(stream)
    selected.sort(key=lambda stream: stream["tap_stream_id"])

    methods = {
        stream["tap_stream_id"]: resolve_replication_method(stream, config) for stream in selected
    }

    # Capture the end LSN once, up front; also validates the server version (SPEC §4.1).
    end_lsn = None
    if any(method == "LOG_BASED" for method in methods.values()):
        end_lsn = logical.fetch_current_lsn(config)
        LOGGER.info("End LSN for this run: %s", logical.int_to_lsn(end_lsn))

    discovery.refresh_streams_schema(config, selected)

    for stream in selected:
        stream_id = stream["tap_stream_id"]
        method = methods[stream_id]
        if method == "LOG_BASED" and stream_utils.is_view(stream):
            msg = f"LOG_BASED replication is not supported for view {stream_id}"
            raise SyncError(msg)
        state = reset_state_on_method_change(
            state, stream_id, method, stream_utils.replication_key(stream)
        )

    traditional: list[dict[str, Any]] = []
    logical_streams: list[dict[str, Any]] = []
    for stream in selected:
        method = methods[stream["tap_stream_id"]]
        if (
            method in ("FULL_TABLE", "INCREMENTAL")
            or classify_log_based_work(state, stream["tap_stream_id"]) == "snapshot"
        ):
            traditional.append(stream)
        else:
            logical_streams.append(stream)

    currently_syncing = bookmarks.get_currently_syncing(state)
    if currently_syncing:
        selected_ids = {stream["tap_stream_id"] for stream in selected}
        if currently_syncing not in selected_ids:
            LOGGER.warning(
                "State says stream %s is currently syncing, but it is no longer selected",
                currently_syncing,
            )
        else:
            traditional.sort(
                key=lambda stream: (
                    stream["tap_stream_id"] != currently_syncing,
                    stream["tap_stream_id"],
                )
            )

    for stream in traditional:
        state = sync_traditional_stream(
            config,
            stream,
            state,
            methods[stream["tap_stream_id"]],
            end_lsn,
            batch_config=batch_config,
        )

    if logical_streams:
        # Drop bookmarks of de-selected LOG_BASED streams so stale positions
        # cannot drag the slot's restart point backwards (SPEC §4.3).
        selected_ids = {stream["tap_stream_id"] for stream in selected}
        for stream_id in list(state["bookmarks"]):
            if stream_id not in selected_ids and "lsn" in state["bookmarks"][stream_id]:
                LOGGER.info("Dropping bookmark of de-selected LOG_BASED stream %s", stream_id)
                del state["bookmarks"][stream_id]

        if end_lsn is None:
            # Unreachable: LOG_BASED streams imply the end LSN was captured above.
            msg = "No end LSN captured for the logical replication phase"
            raise SyncError(msg)

        groups: dict[str, list[dict[str, Any]]] = {}
        for stream in logical_streams:
            groups.setdefault(_database_name(stream) or config["dbname"], []).append(stream)
        for dbname in sorted(groups):
            state = logical.sync_logical_streams(
                config,
                groups[dbname],
                state,
                end_lsn,
                state_file,
                dbname,
            )

    stream_utils.write_state_message(state)
    return state

"""LOG_BASED replication via wal2json format version 2 (SPEC §6.3)."""

from __future__ import annotations

import datetime
import json
import re
import select
import sys
import time
from decimal import Decimal, InvalidOperation
from typing import TYPE_CHECKING, Any

import dateutil.parser
import psycopg2
import psycopg2.extras
import singer
from singer import utils

from tap_postgres import config as cfg
from tap_postgres import db, discovery, stream_utils

if TYPE_CHECKING:
    from pathlib import Path

if sys.version_info < (3, 11):
    from backports.datetime_fromisoformat import MonkeyPatch

    MonkeyPatch.patch_fromisoformat()


LOGGER = singer.get_logger()

# Operators create replication slots by hand with exactly this prefix (SPEC §6.3.2).
SLOT_PREFIX = "tap_postgres"

# Fallback prefix for slots created by the legacy pipelinewise-tap-postgres tap, so
# customers migrating from it don't need to recreate their replication slot.
LEGACY_SLOT_PREFIX = "pipelinewise"

FALLBACK_TIMESTAMP = "9999-12-31T23:59:59.999+00:00"
FALLBACK_DATE = "9999-12-31T00:00:00+00:00"
_MAX_NAIVE_TIMESTAMP = datetime.datetime(9999, 12, 31, 23, 59, 59, 999000)

UPDATE_BOOKMARK_PERIOD = 10_000  # fully-processed LSN advances between STATE messages
FEEDBACK_INTERVAL_SECONDS = 10
WAL_SENDER_TIMEOUT_MS = 10_800_000  # 3 hours, applied on servers >= 12

# Element types wal2json array literals can be cast back to losslessly;
# everything else is reconstructed through text[] (SPEC §6.3.6).
NATIVE_ARRAY_CAST_TYPES = {
    "boolean",
    "character varying",
    "cidr",
    "double precision",
    "inet",
    "integer",
    "macaddr",
    "real",
    "smallint",
}


class LogicalReplicationError(Exception):
    """Unrecoverable problem in the logical replication path."""


class UnsupportedPayloadError(LogicalReplicationError):
    """A wal2json payload with an action other than I/U/D."""


# ---------------------------------------------------------------------------
# LSN arithmetic (SPEC §6.3.3)


def lsn_to_int(lsn: str | None) -> int | None:
    """Convert PostgreSQL `file/offset` hex notation to a single integer."""
    if not lsn:
        return None
    file_part, offset = lsn.split("/")
    return (int(file_part, 16) << 32) + int(offset, 16)


def int_to_lsn(lsn: int | None) -> str | None:
    """Convert the integer form back to `file/offset` hex notation."""
    if lsn is None:
        return None
    return f"{lsn >> 32:X}/{lsn & 0xFFFFFFFF:X}"


# ---------------------------------------------------------------------------
# Server version gate (SPEC §6.3.1)

# (lower bound of the version line, first fixed version)
_BUGGY_VERSION_RANGES = (
    (90400, 90421),
    (90500, 90516),
    (90600, 90612),
    (100000, 100007),
    (110000, 110002),
)


def validate_server_version(version: int) -> None:
    if version < 90400:
        msg = f"Logical replication requires PostgreSQL 9.4 or newer (server reports {version})"
        raise LogicalReplicationError(msg)
    for line_start, first_fixed in _BUGGY_VERSION_RANGES:
        if line_start <= version < first_fixed:
            msg = (
                f"PostgreSQL server version {version} is affected by a known WAL bug; "
                f"upgrade to at least {first_fixed}"
            )
            raise LogicalReplicationError(msg)


def fetch_current_lsn(config: dict[str, Any]) -> int:
    """Read the primary's current WAL LSN, validating the server version (SPEC §4.1)."""
    connection = db.open_connection(config, primary=True)
    try:
        validate_server_version(connection.server_version)
        lsn_function = (
            "pg_current_wal_lsn()"
            if connection.server_version >= 100000
            else "pg_current_xlog_location()"
        )
        current_lsn = lsn_to_int(db.fetch_scalar(connection, f"SELECT {lsn_function}"))
    finally:
        connection.close()
    if current_lsn is None:
        msg = "The server did not report a current WAL LSN"
        raise LogicalReplicationError(msg)
    return current_lsn


# ---------------------------------------------------------------------------
# Replication slots (SPEC §6.3.2)


def generate_slot_name(dbname: str, tap_id: str | None = None, prefix: str = SLOT_PREFIX) -> str:
    raw = f"{prefix}_{dbname}_{tap_id}" if tap_id else f"{prefix}_{dbname}"
    return re.sub(r"[^a-z0-9_]", "_", raw.lower())


def locate_replication_slot_by_cur(
    cursor: db.CursorProtocol,
    dbname: str,
    tap_id: str | None = None,
) -> str:
    """Probe the un-suffixed name first, then the suffixed one, then the same two
    under the legacy pipelinewise-tap-postgres prefix for migrated deployments."""
    candidates = [generate_slot_name(dbname)]
    if tap_id:
        candidates.append(generate_slot_name(dbname, tap_id))
    candidates.append(generate_slot_name(dbname, prefix=LEGACY_SLOT_PREFIX))
    if tap_id:
        candidates.append(generate_slot_name(dbname, tap_id, prefix=LEGACY_SLOT_PREFIX))
    for candidate in candidates:
        cursor.execute(
            "SELECT slot_name FROM pg_replication_slots WHERE slot_name = %s", (candidate,)
        )
        if cursor.fetchone():
            LOGGER.info("Using pg_replication_slot %s", candidate)
            return candidate
    msg = f"Unable to find replication slot {' or '.join(candidates)} with wal2json output plugin"
    raise LogicalReplicationError(msg)


def locate_replication_slot(
    connection: db.ConnectionProtocol,
    dbname: str,
    tap_id: str | None = None,
) -> str:
    with connection.cursor() as cur:
        return locate_replication_slot_by_cur(cur, dbname, tap_id)


# ---------------------------------------------------------------------------
# wal2json options (SPEC §6.3.5)


def escape_wal2json_name(name: str) -> str:
    """Backslash-escape space, single quote, comma, period and asterisk."""
    return re.sub(r"([\\ ',.*])", r"\\\1", name)


def build_add_tables(streams: list[dict[str, Any]]) -> str:
    tables = []
    for stream in streams:
        schema_name = stream_utils.schema_name(stream)
        tables.append(
            f"{escape_wal2json_name(schema_name)}.{escape_wal2json_name(stream['table_name'])}"
        )
    return ",".join(tables)


def add_automatic_properties(stream: dict[str, Any], debug_lsn: bool) -> dict[str, Any]:
    """Add `_sdc_deleted_at` (and `_sdc_lsn` under debug_lsn) to the stream schema."""
    properties = stream["schema"]["properties"]
    properties["_sdc_deleted_at"] = {"type": ["null", "string"], "format": "date-time"}
    if debug_lsn:
        properties["_sdc_lsn"] = {"type": ["null", "string"]}
    else:
        properties.pop("_sdc_lsn", None)
    return stream


# ---------------------------------------------------------------------------
# Value decoding (SPEC §6.3.6)


def parse_logical_timestamp(value: Any) -> str:  # ruff:ignore[any-type]
    """wal2json timestamps to ISO-8601, degrading to the max sentinel (SPEC §6.3.6)."""
    if isinstance(value, datetime.datetime):
        parsed = value
    else:
        text = str(value)
        if text.endswith(" BC"):
            return FALLBACK_TIMESTAMP
        try:
            parsed = dateutil.parser.parse(text)
        except (ValueError, OverflowError):
            return FALLBACK_TIMESTAMP

    if parsed.tzinfo is None:
        if parsed > _MAX_NAIVE_TIMESTAMP:
            return FALLBACK_TIMESTAMP
        return parsed.isoformat() + "+00:00"
    try:
        as_utc = parsed.astimezone(datetime.timezone.utc)
    except (OverflowError, ValueError):
        return FALLBACK_TIMESTAMP
    if as_utc.replace(tzinfo=None) > _MAX_NAIVE_TIMESTAMP:
        return FALLBACK_TIMESTAMP
    return parsed.isoformat()


def parse_logical_date(value: Any) -> str:  # ruff:ignore[any-type]
    """Dates to ISO-8601 midnight; years above 9999 degrade, other failures are fatal."""
    if isinstance(value, datetime.date):
        return value.isoformat() + "T00:00:00+00:00"
    text = str(value)
    year_match = re.match(r"^(\d+)-\d{2}-\d{2}$", text)
    if year_match and int(year_match.group(1)) > 9999:
        return FALLBACK_DATE
    return datetime.date.fromisoformat(text).isoformat() + "T00:00:00+00:00"


def reconstruct_array(literal: Any, element_type: str, connection: Any) -> list | None:  # ruff:ignore[any-type]
    """Cast a PostgreSQL array literal back to a typed array on the server."""
    cast_type = element_type if element_type in NATIVE_ARRAY_CAST_TYPES else "text"
    return db.fetch_scalar(connection, f"SELECT %s::{cast_type}[]", (literal,))


def explode_hstore(literal: str, connection: db.ConnectionProtocol) -> dict[str, Any]:
    """Ask the server to explode an hstore literal into a key/value array."""
    flat = db.fetch_scalar(connection, "SELECT hstore_to_array(%s::hstore)", (literal,)) or []
    return dict(zip(flat[::2], flat[1::2], strict=True))


def selected_value_to_singer_value(value: Any, sql_datatype: str, connection_supplier: Any) -> Any:  # ruff:ignore[any-type]
    """Decode one wal2json value using the column's catalog datatype (SPEC §6.3.6)."""
    if value is None:
        return None

    if sql_datatype.endswith("[]"):
        element_type = sql_datatype[:-2]
        if isinstance(value, str):
            value = reconstruct_array(value, element_type, connection_supplier())
        if value is None:
            return None
        return [
            selected_value_to_singer_value(element, element_type, connection_supplier)
            if not isinstance(element, list)
            else [
                selected_value_to_singer_value(sub, element_type, connection_supplier)
                for sub in element
            ]
            for element in value
        ]

    if sql_datatype in ("timestamp without time zone", "timestamp with time zone"):
        return parse_logical_timestamp(value)
    if sql_datatype == "date":
        return parse_logical_date(value)
    if sql_datatype == "time with time zone":
        from tap_postgres.conversion import convert_time

        return convert_time(value, with_timezone=True)
    if sql_datatype == "time without time zone":
        from tap_postgres.conversion import convert_time

        return convert_time(value, with_timezone=False)
    if sql_datatype == "bit":
        return value == "1" if isinstance(value, str) else bool(value)
    if sql_datatype == "boolean":
        return value if isinstance(value, bool) else str(value).lower() in ("t", "true", "1")
    if sql_datatype in ("numeric", "decimal") or sql_datatype.startswith(("numeric(", "decimal(")):
        try:
            decimal_value = Decimal(str(value))
        except InvalidOperation as exc:
            msg = f"Cannot decode numeric value {value!r}"
            raise LogicalReplicationError(msg) from exc
        return None if decimal_value.is_nan() else decimal_value
    if sql_datatype == "money":
        return str(value)
    if sql_datatype in ("json", "jsonb"):
        return json.loads(value) if isinstance(value, str) else value
    if sql_datatype == "hstore":
        if isinstance(value, dict):
            return value
        return explode_hstore(value, connection_supplier())
    if sql_datatype in ("smallint", "integer", "bigint"):
        return int(value)
    if sql_datatype in ("real", "double precision"):
        as_float = float(value)
        import math

        return None if (math.isnan(as_float) or math.isinf(as_float)) else as_float

    if isinstance(value, (bool, int, float, str)):
        return value
    msg = f"Cannot decode value of class {type(value).__name__} for datatype {sql_datatype}"
    raise LogicalReplicationError(msg)


# ---------------------------------------------------------------------------
# Message processing (SPEC §6.3.6)


def row_to_singer_message(
    stream: dict[str, Any],
    row: dict[str, Any],
    version: int,
    time_extracted: datetime.datetime,
) -> singer.RecordMessage:
    return singer.RecordMessage(
        stream=stream_utils.dest_stream_name(stream),
        record=row,
        version=version,
        time_extracted=time_extracted,
    )


class LogicalSession:
    """One streaming replication session covering all pure-logical streams of a database."""

    def __init__(
        self,
        config: dict[str, Any],
        streams: list[dict[str, Any]],
        state: dict[str, Any],
        end_lsn: int,
        state_file: Path | None,
        dbname: str,
    ) -> None:
        self.config = config
        self.state = state
        self.end_lsn = end_lsn
        self.state_file = state_file
        self.dbname = dbname
        self.debug_lsn = cfg.debug_lsn(config)
        self.time_extracted = utils.now()

        self.streams = {}
        for stream in streams:
            self.streams[stream_utils.schema_name(stream), stream["table_name"]] = stream

        self.stream_ids = [s["tap_stream_id"] for s in streams]
        self.committed_lsn = self._committed_min_lsn(state)
        self.flushed_lsn: int | None = None
        self.last_processed_lsn: int | None = None
        self.last_fully_processed_lsn: int | None = None
        self.processed_advances = 0
        self.received_first_message = False
        self.rows_synced: dict[str, int] = {}
        self._helper_connection: db.ConnectionProtocol | None = None

    # -- helpers -----------------------------------------------------------

    def _committed_min_lsn(self, state: dict[str, Any]) -> int | None:
        lsns = [singer.get_bookmark(state, stream_id, "lsn") for stream_id in self.stream_ids]
        lsns = [lsn for lsn in lsns if lsn is not None]
        return min(lsns) if lsns else None

    def helper_connection(self) -> db.ConnectionProtocol:
        """Primary-side connection for array/hstore reconstruction (SPEC §2.3)."""
        if self._helper_connection is None or self._helper_connection.closed:
            self._helper_connection = db.open_connection(
                self.config, primary=True, dbname=self.dbname
            )
        return self._helper_connection

    def close(self) -> None:
        if self._helper_connection is not None and not self._helper_connection.closed:
            self._helper_connection.close()

    # -- message consumption ------------------------------------------------

    def consume_message(self, payload: str, lsn: int) -> None:
        try:
            message = json.loads(payload)
        except (ValueError, TypeError):
            # SPEC §10.2.6: never skip silently.
            LOGGER.warning(
                "Skipping unparseable wal2json payload at %s: %.200s", int_to_lsn(lsn), payload
            )
            self.record_processed(lsn)
            return

        action = message.get("action")
        stream = self.streams.get((message.get("schema"), message.get("table")))
        if stream is None:
            self.record_processed(lsn)
            return
        if action not in ("I", "U", "D"):
            msg = f"Unsupported payload action {action!r}"
            raise UnsupportedPayloadError(msg)

        stream_id = stream["tap_stream_id"]
        version = singer.get_bookmark(self.state, stream_id, "version")
        if version is None:
            msg = f"No version bookmark for stream {stream_id}"
            raise LogicalReplicationError(msg)

        if action in ("I", "U"):
            payload_columns = message.get("columns", [])
            self._maybe_refresh_schema(stream, payload_columns)
            source_columns = payload_columns
            deleted_at = None
        else:
            source_columns = message.get("identity", [])
            deleted_at = singer.utils.strftime(self.time_extracted)

        selected = set(stream_utils.selected_columns(stream))
        row: dict[str, Any] = {}
        for entry in source_columns:
            name = entry.get("name")
            if name not in selected:
                continue
            datatype = stream_utils.sql_datatype_for_column(stream, name)
            if datatype is None:
                msg = f"No sql-datatype metadata for column {name} of stream {stream_id}"
                raise LogicalReplicationError(msg)
            row[name] = selected_value_to_singer_value(
                entry.get("value"), datatype, self.helper_connection
            )
        row["_sdc_deleted_at"] = deleted_at
        if self.debug_lsn:
            row["_sdc_lsn"] = str(lsn)

        singer.write_message(row_to_singer_message(stream, row, version, self.time_extracted))
        self.rows_synced[stream_id] = self.rows_synced.get(stream_id, 0) + 1
        self.state = singer.write_bookmark(self.state, stream_id, "lsn", lsn)
        self.record_processed(lsn)

    def _maybe_refresh_schema(
        self, stream: dict[str, Any], payload_columns: list[dict[str, Any]]
    ) -> None:
        """Schema drift: unknown payload columns refresh the stream schema (SPEC §6.3.6)."""
        known = set(stream["schema"]["properties"])
        incoming = {entry.get("name") for entry in payload_columns}
        if incoming - known:
            LOGGER.info("Schema drift detected on %s: refreshing schema", stream["tap_stream_id"])
            discovery.refresh_streams_schema(self.config, [stream], dbname=self.dbname)
            add_automatic_properties(stream, self.debug_lsn)
            stream_utils.write_schema_message(stream, bookmark_properties=["lsn"])

    def record_processed(self, lsn: int) -> None:
        """A message's LSN is only "fully processed" once a higher LSN arrives (SPEC §6.3.7)."""
        if self.last_processed_lsn is not None and lsn > self.last_processed_lsn:
            self.last_fully_processed_lsn = self.last_processed_lsn
            self.processed_advances += 1
            if self.processed_advances % UPDATE_BOOKMARK_PERIOD == 0:
                self.write_all_bookmarks(self.last_fully_processed_lsn)
                stream_utils.write_state_message(self.state)
        self.last_processed_lsn = lsn

    def write_all_bookmarks(self, lsn: int) -> None:
        for stream_id in self.stream_ids:
            self.state = singer.write_bookmark(self.state, stream_id, "lsn", lsn)

    # -- flush control (SPEC §6.3.7) ----------------------------------------

    def flush_on_first_message(
        self,
        cursor: psycopg2.extras.ReplicationCursor,
        first_lsn: int,
    ) -> None:
        if self.received_first_message:
            return
        self.received_first_message = True
        flush_to = first_lsn if self.committed_lsn is None else min(self.committed_lsn, first_lsn)
        LOGGER.info("First message received; flushing slot to %s", int_to_lsn(flush_to))
        cursor.send_feedback(flush_lsn=flush_to, force=True)
        self.flushed_lsn = flush_to

    def refresh_committed_lsn_from_state_file(
        self,
        cursor: psycopg2.extras.ReplicationCursor,
    ) -> None:
        """Re-read the state file; advance the flush position only past data the
        downstream target has durably committed."""
        if not self.state_file:
            return
        try:
            file_state = utils.load_json(self.state_file)
        except Exception:
            return  # read failures are ignored silently (SPEC §6.3.7)
        committed = self._committed_min_lsn(file_state)
        if committed is None:
            return
        if self.committed_lsn is None or committed > self.committed_lsn:
            self.committed_lsn = committed
        behind_current = self.last_processed_lsn is None or committed <= self.last_processed_lsn
        already_flushed = self.flushed_lsn is not None and committed <= self.flushed_lsn
        if behind_current and not already_flushed:
            LOGGER.info(
                "Downstream committed LSN advanced; flushing slot to %s", int_to_lsn(committed)
            )
            cursor.send_feedback(flush_lsn=committed, force=True)
            self.flushed_lsn = committed

    # -- session end ---------------------------------------------------------

    def finalize(self) -> dict[str, Any]:
        if self.last_fully_processed_lsn is not None:
            final_lsn = self.last_fully_processed_lsn
            if self.committed_lsn is not None:
                final_lsn = max(final_lsn, self.committed_lsn)
            self.write_all_bookmarks(final_lsn)
        for stream_id, count in self.rows_synced.items():
            LOGGER.info("Stream %s: %s records synced from WAL", stream_id, count)
        stream_utils.write_state_message(self.state)
        return self.state


def sync_logical_streams(
    config: dict[str, Any],
    streams: list[dict[str, Any]],
    state: dict[str, Any],
    end_lsn: int,
    state_file: Path | None,
    dbname: str,
) -> dict[str, Any]:
    """Stream WAL changes for all pure-logical streams of one database (SPEC §6.3.5)."""
    LOGGER.info("Starting logical replication for %s", [s["tap_stream_id"] for s in streams])
    debug_lsn = cfg.debug_lsn(config)
    for stream in streams:
        add_automatic_properties(stream, debug_lsn)
        stream_utils.write_schema_message(stream, bookmark_properties=["lsn"])

    session = LogicalSession(config, streams, state, end_lsn, state_file, dbname)
    start_lsn = session.committed_lsn or 0

    lookup_connection = db.open_connection(config, primary=True, dbname=dbname)
    try:
        server_version = lookup_connection.server_version
        slot = locate_replication_slot(lookup_connection, dbname, config.get("tap_id"))
    finally:
        lookup_connection.close()

    extra_options = None
    if server_version >= 120000:
        extra_options = f"-c wal_sender_timeout={WAL_SENDER_TIMEOUT_MS}"

    replication_connection = db.open_connection(
        config,
        primary=True,
        dbname=dbname,
        connection_factory=psycopg2.extras.LogicalReplicationConnection,
        extra_options=extra_options,
    )
    cursor = replication_connection.cursor()

    wal2json_options = {
        "format-version": "2",
        "include-transaction": "false",
        "include-timestamp": "true",
        "include-types": "false",
        "actions": "insert,update,delete",
        "add-tables": build_add_tables(streams),
    }
    LOGGER.info(
        "Starting replication on slot %s from %s (end LSN %s)",
        slot,
        int_to_lsn(start_lsn),
        int_to_lsn(end_lsn),
    )
    try:
        cursor.start_replication(
            slot_name=slot,
            decode=True,
            start_lsn=start_lsn,
            status_interval=FEEDBACK_INTERVAL_SECONDS,
            options=wal2json_options,
        )
    except psycopg2.ProgrammingError as exc:
        msg = f"Unable to start replication on slot {slot}: {exc}"
        raise LogicalReplicationError(msg) from exc

    max_run_seconds = cfg.max_run_seconds(config)
    poll_total_seconds = cfg.logical_poll_total_seconds(config)
    break_at_end = cfg.break_at_end_lsn(config)

    session_start = time.monotonic()
    last_data_received = time.monotonic()
    last_feedback = time.monotonic()

    try:
        while True:
            now = time.monotonic()
            if now - session_start > max_run_seconds:
                LOGGER.info("Stopping: max_run_seconds (%s) reached", max_run_seconds)
                break
            if now - last_data_received > poll_total_seconds:
                LOGGER.info(
                    "Stopping: no data received for logical_poll_total_seconds (%s)",
                    poll_total_seconds,
                )
                break

            if now - last_feedback > FEEDBACK_INTERVAL_SECONDS:
                # Request a reply: wal_sender_timeout is set high (below) to avoid the
                # server dropping an idle connection, which also suppresses its own
                # unsolicited keepalives. Without reply=True, cursor.wal_end would only
                # refresh once every wal_sender_timeout/2, defeating the end_lsn check.
                cursor.send_feedback(force=True, reply=True)
                session.refresh_committed_lsn_from_state_file(cursor)
                last_feedback = now

            message = cursor.read_message()
            if message is None:
                # A keepalive updates cursor.wal_end without producing a message; if the
                # server has already reported a position past end_lsn, don't wait out
                # logical_poll_total_seconds for an XLogData message that may never come.
                if break_at_end and cursor.wal_end > end_lsn:
                    LOGGER.info(
                        "Stopping: keepalive-reported WAL position %s is beyond end LSN %s",
                        int_to_lsn(cursor.wal_end),
                        int_to_lsn(end_lsn),
                    )
                    break
                # Block on the socket for up to a second, then loop (SPEC §6.3.5).
                select.select([cursor], [], [], 1.0)
                continue

            last_data_received = time.monotonic()
            if break_at_end and message.data_start > end_lsn:
                LOGGER.info(
                    "Stopping: message LSN %s is beyond end LSN %s",
                    int_to_lsn(message.data_start),
                    int_to_lsn(end_lsn),
                )
                break
            session.flush_on_first_message(cursor, message.data_start)
            session.consume_message(message.payload, message.data_start)
    finally:
        state = session.finalize()
        session.close()
        cursor.close()
        replication_connection.close()

    return state
